package com.dixitdada.journalApp.entity; import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.validation.constraints.*; import lombok.*; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document; import java.util.*; @Data @Builder @NoArgsConstructor @AllArgsConstructor @Document("users") public class User { @Id private String id; @NotBlank @Indexed(unique=true) private String username; @JsonIgnore @NotBlank private String password; @Email private String email; @Builder.Default private List<String> roles=new ArrayList<>(List.of("USER")); @Builder.Default private List<String> journalEntryIds=new ArrayList<>(); @Builder.Default private boolean sentimentAnalysis=false; }